PRAGMA application_id=1179472689;
PRAGMA user_version=2;
CREATE TABLE IF NOT EXISTS Company(Id INTEGER PRIMARY KEY CHECK(Id=1),Name TEXT NOT NULL DEFAULT '',Address TEXT NOT NULL DEFAULT '',GSTIN TEXT NOT NULL DEFAULT '',StateCode TEXT NOT NULL DEFAULT '',PAN TEXT NOT NULL DEFAULT '',Mobile TEXT NOT NULL DEFAULT '',Email TEXT NOT NULL DEFAULT '',Website TEXT NOT NULL DEFAULT '',Currency TEXT NOT NULL DEFAULT 'INR',Logo BLOB,ShowLogo INTEGER NOT NULL DEFAULT 1,LogoPosition TEXT NOT NULL DEFAULT 'Left');
INSERT OR IGNORE INTO Company(Id) VALUES(1);
CREATE TABLE IF NOT EXISTS AppUser(Id INTEGER PRIMARY KEY,Name TEXT NOT NULL UNIQUE,Salt BLOB NOT NULL,Hash BLOB NOT NULL,Iterations INTEGER NOT NULL,Failed INTEGER NOT NULL DEFAULT 0,LockedUntil INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS Setting(Key TEXT PRIMARY KEY,Value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Account(Code TEXT PRIMARY KEY,Name TEXT NOT NULL,Category TEXT NOT NULL CHECK(Category IN ('Asset','Liability','Equity','Income','Expense')));
CREATE TABLE IF NOT EXISTS Party(Id INTEGER PRIMARY KEY,Kind TEXT NOT NULL CHECK(Kind IN ('Customer','Supplier')),Code TEXT NOT NULL,Name TEXT NOT NULL,Address TEXT NOT NULL DEFAULT '',GSTIN TEXT NOT NULL DEFAULT '',StateCode TEXT NOT NULL DEFAULT '',ContactPerson TEXT NOT NULL DEFAULT '',Mobile TEXT NOT NULL DEFAULT '',Email TEXT NOT NULL DEFAULT '',CreditDays INTEGER NOT NULL DEFAULT 0 CHECK(CreditDays>=0),Active INTEGER NOT NULL DEFAULT 1,Remarks TEXT NOT NULL DEFAULT '',UNIQUE(Kind,Code));
CREATE TABLE IF NOT EXISTS Employee(Id INTEGER PRIMARY KEY,Code TEXT NOT NULL UNIQUE,Name TEXT NOT NULL,Designation TEXT NOT NULL DEFAULT '',Department TEXT NOT NULL DEFAULT '',JoinDay INTEGER NOT NULL,LeaveDay INTEGER,Salary INTEGER NOT NULL CHECK(typeof(Salary)='integer' AND Salary>=0),EPF INTEGER NOT NULL DEFAULT 0,ESIC INTEGER NOT NULL DEFAULT 0,UAN TEXT NOT NULL DEFAULT '',IPNumber TEXT NOT NULL DEFAULT '',BankName TEXT NOT NULL DEFAULT '',AccountNumber TEXT NOT NULL DEFAULT '',IFSC TEXT NOT NULL DEFAULT '',Active INTEGER NOT NULL DEFAULT 1,Remarks TEXT NOT NULL DEFAULT '',CHECK(LeaveDay IS NULL OR LeaveDay>=JoinDay));
CREATE TABLE IF NOT EXISTS Bank(Id INTEGER PRIMARY KEY,Name TEXT NOT NULL,Branch TEXT NOT NULL DEFAULT '',AccountNumber TEXT NOT NULL UNIQUE,AccountType TEXT NOT NULL DEFAULT 'Current',IFSC TEXT NOT NULL DEFAULT '',Cash INTEGER NOT NULL DEFAULT 0,Active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS Site(Id INTEGER PRIMARY KEY,Code TEXT NOT NULL UNIQUE,Name TEXT NOT NULL,Location TEXT NOT NULL DEFAULT '',PartyId INTEGER REFERENCES Party(Id),StartDay INTEGER,EndDay INTEGER,Status TEXT NOT NULL DEFAULT 'Active',Remarks TEXT NOT NULL DEFAULT '',CHECK(EndDay IS NULL OR StartDay IS NULL OR EndDay>=StartDay));
CREATE TABLE IF NOT EXISTS Item(Id INTEGER PRIMARY KEY,Code TEXT NOT NULL UNIQUE,Name TEXT NOT NULL,Description TEXT NOT NULL DEFAULT '',HSN TEXT NOT NULL DEFAULT '',Unit TEXT NOT NULL DEFAULT '',Rate INTEGER NOT NULL CHECK(typeof(Rate)='integer' AND Rate>=0),GSTRate TEXT NOT NULL DEFAULT '18',Active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS Category(Id INTEGER PRIMARY KEY,Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Statutory(Id INTEGER PRIMARY KEY,EffectiveDay INTEGER NOT NULL UNIQUE,BasicPercent TEXT NOT NULL,EPFRate TEXT NOT NULL,EPFCeiling INTEGER NOT NULL,CapEPF INTEGER NOT NULL,EPFBasis TEXT NOT NULL,ESICRate TEXT NOT NULL,ESICCeiling INTEGER NOT NULL,ESICBasis TEXT NOT NULL,EPFRounding TEXT NOT NULL,ESICRounding TEXT NOT NULL,SalaryRounding TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS PeriodLock(Id INTEGER PRIMARY KEY,FromDay INTEGER NOT NULL,ToDay INTEGER NOT NULL,Locked INTEGER NOT NULL,Reason TEXT NOT NULL,CHECK(ToDay>=FromDay));
CREATE TABLE IF NOT EXISTS Sequence(FY TEXT NOT NULL,Kind TEXT NOT NULL,Next INTEGER NOT NULL,PRIMARY KEY(FY,Kind));
CREATE TABLE IF NOT EXISTS Voucher(Id INTEGER PRIMARY KEY,Token TEXT NOT NULL UNIQUE,Kind TEXT NOT NULL,Number TEXT NOT NULL,Day INTEGER NOT NULL,FY TEXT NOT NULL,Narration TEXT NOT NULL,UserId INTEGER NOT NULL REFERENCES AppUser(Id),CreatedUtc TEXT NOT NULL,ReversalOf INTEGER UNIQUE REFERENCES Voucher(Id),ReversedBy INTEGER REFERENCES Voucher(Id),UNIQUE(FY,Kind,Number));
CREATE TABLE IF NOT EXISTS Instrument(Id INTEGER PRIMARY KEY,Kind TEXT NOT NULL CHECK(Kind IN ('FD','Employee Loan','Business Loan')),Number TEXT NOT NULL,EmployeeId INTEGER REFERENCES Employee(Id),BankId INTEGER REFERENCES Bank(Id),Lender TEXT NOT NULL DEFAULT '',Type TEXT NOT NULL DEFAULT '',Day INTEGER NOT NULL,MaturityDay INTEGER,Principal INTEGER NOT NULL CHECK(typeof(Principal)='integer' AND Principal>0),Rate TEXT NOT NULL DEFAULT '0',MaturityAmount INTEGER NOT NULL DEFAULT 0,EMI INTEGER NOT NULL DEFAULT 0,RecoveryDay INTEGER,Installments INTEGER NOT NULL DEFAULT 0,Status TEXT NOT NULL DEFAULT 'Active',ClosureDay INTEGER,Remarks TEXT NOT NULL DEFAULT '',UNIQUE(Kind,Number),CHECK(MaturityDay IS NULL OR MaturityDay>=Day));
CREATE TABLE IF NOT EXISTS Posting(Id INTEGER PRIMARY KEY,VoucherId INTEGER NOT NULL REFERENCES Voucher(Id),Account TEXT NOT NULL REFERENCES Account(Code),Amount INTEGER NOT NULL CHECK(typeof(Amount)='integer' AND Amount<>0),PartyId INTEGER REFERENCES Party(Id),EmployeeId INTEGER REFERENCES Employee(Id),BankId INTEGER REFERENCES Bank(Id),SiteId INTEGER REFERENCES Site(Id),InstrumentId INTEGER REFERENCES Instrument(Id),CategoryId INTEGER REFERENCES Category(Id));
CREATE TRIGGER IF NOT EXISTS PostingNoEdit BEFORE UPDATE ON Posting BEGIN SELECT RAISE(ABORT,'Posted lines are immutable'); END;
CREATE TRIGGER IF NOT EXISTS PostingNoDelete BEFORE DELETE ON Posting BEGIN SELECT RAISE(ABORT,'Posted lines cannot be deleted'); END;
CREATE TABLE IF NOT EXISTS Invoice(Id INTEGER PRIMARY KEY,Kind TEXT NOT NULL CHECK(Kind IN ('Sales','Purchase')),FY TEXT NOT NULL,Number TEXT NOT NULL,PartyId INTEGER NOT NULL REFERENCES Party(Id),Day INTEGER NOT NULL,DueDay INTEGER NOT NULL,PlaceOfSupply TEXT NOT NULL,CompanyState TEXT NOT NULL,PartyState TEXT NOT NULL,PartyGSTIN TEXT NOT NULL,CompanyGSTIN TEXT NOT NULL,Reference TEXT NOT NULL,Remarks TEXT NOT NULL,Taxable INTEGER NOT NULL,CGST INTEGER NOT NULL,SGST INTEGER NOT NULL,IGST INTEGER NOT NULL,RoundOff INTEGER NOT NULL,Total INTEGER NOT NULL,ITC INTEGER NOT NULL DEFAULT 1,PurchaseAccount TEXT NOT NULL DEFAULT 'PURCHASE' REFERENCES Account(Code),VoucherId INTEGER UNIQUE REFERENCES Voucher(Id),Cancelled INTEGER NOT NULL DEFAULT 0,CHECK(DueDay>=Day));
CREATE UNIQUE INDEX IF NOT EXISTS UX_Sale ON Invoice(FY,Number) WHERE Kind='Sales';
CREATE UNIQUE INDEX IF NOT EXISTS UX_Purchase ON Invoice(FY,PartyId,Number) WHERE Kind='Purchase';
CREATE TABLE IF NOT EXISTS InvoiceLine(Id INTEGER PRIMARY KEY,InvoiceId INTEGER NOT NULL REFERENCES Invoice(Id),ItemId INTEGER REFERENCES Item(Id),Description TEXT NOT NULL,HSN TEXT NOT NULL,Quantity TEXT NOT NULL,Unit TEXT NOT NULL,Rate INTEGER NOT NULL,Discount INTEGER NOT NULL,GSTRate TEXT NOT NULL,Taxable INTEGER NOT NULL,CGST INTEGER NOT NULL,SGST INTEGER NOT NULL,IGST INTEGER NOT NULL,Total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS Allocation(Id INTEGER PRIMARY KEY,VoucherId INTEGER NOT NULL REFERENCES Voucher(Id),InvoiceId INTEGER NOT NULL REFERENCES Invoice(Id),Amount INTEGER NOT NULL CHECK(typeof(Amount)='integer' AND Amount>0),UNIQUE(VoucherId,InvoiceId));
CREATE TABLE IF NOT EXISTS Payroll(Id INTEGER PRIMARY KEY,Year INTEGER NOT NULL,Month INTEGER NOT NULL CHECK(Month BETWEEN 1 AND 12),Revision INTEGER NOT NULL,SettingId INTEGER NOT NULL REFERENCES Statutory(Id),Status TEXT NOT NULL,Day INTEGER NOT NULL,VoucherId INTEGER UNIQUE REFERENCES Voucher(Id),UNIQUE(Year,Month,Revision));
CREATE UNIQUE INDEX IF NOT EXISTS UX_PayrollActive ON Payroll(Year,Month) WHERE Status='Finalized';
CREATE TABLE IF NOT EXISTS PayrollRow(Id INTEGER PRIMARY KEY,PayrollId INTEGER NOT NULL REFERENCES Payroll(Id),EmployeeId INTEGER NOT NULL REFERENCES Employee(Id),Snapshot TEXT NOT NULL,Net INTEGER NOT NULL CHECK(typeof(Net)='integer' AND Net>=0),UNIQUE(PayrollId,EmployeeId));
CREATE TABLE IF NOT EXISTS SalaryAllocation(Id INTEGER PRIMARY KEY,VoucherId INTEGER NOT NULL REFERENCES Voucher(Id),PayrollRowId INTEGER NOT NULL REFERENCES PayrollRow(Id),Amount INTEGER NOT NULL CHECK(typeof(Amount)='integer' AND Amount>0));
CREATE TABLE IF NOT EXISTS BG(Id INTEGER PRIMARY KEY,Number TEXT NOT NULL UNIQUE,Day INTEGER NOT NULL,BankId INTEGER NOT NULL REFERENCES Bank(Id),Branch TEXT NOT NULL DEFAULT '',Beneficiary TEXT NOT NULL,Amount INTEGER NOT NULL CHECK(typeof(Amount)='integer' AND Amount>0),Type TEXT NOT NULL,Purpose TEXT NOT NULL,ExpiryDay INTEGER NOT NULL,ClaimDay INTEGER NOT NULL,Dispatch TEXT NOT NULL DEFAULT '',DeliveredDay INTEGER,Confirmed INTEGER NOT NULL DEFAULT 0,Status TEXT NOT NULL DEFAULT 'Active',ClosureDay INTEGER,Remarks TEXT NOT NULL DEFAULT '',CHECK(ExpiryDay>=Day AND ClaimDay>=ExpiryDay));
CREATE TABLE IF NOT EXISTS BGFD(Id INTEGER PRIMARY KEY,BGId INTEGER NOT NULL REFERENCES BG(Id),FDId INTEGER NOT NULL REFERENCES Instrument(Id),LinkedDay INTEGER NOT NULL,ReleasedDay INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS UX_FDLien ON BGFD(FDId) WHERE ReleasedDay IS NULL;
CREATE TABLE IF NOT EXISTS BGCharge(VoucherId INTEGER PRIMARY KEY REFERENCES Voucher(Id),BGId INTEGER NOT NULL REFERENCES BG(Id));
CREATE TABLE IF NOT EXISTS Attachment(Id INTEGER PRIMARY KEY,Entity TEXT NOT NULL,EntityId INTEGER NOT NULL,Name TEXT NOT NULL,Mime TEXT NOT NULL,Data BLOB NOT NULL,SHA256 TEXT NOT NULL,CreatedUtc TEXT NOT NULL,Removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS Reconciliation(Id INTEGER PRIMARY KEY,PostingId INTEGER NOT NULL UNIQUE REFERENCES Posting(Id),StatementDay INTEGER NOT NULL,Reference TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Audit(Id INTEGER PRIMARY KEY,UserId INTEGER REFERENCES AppUser(Id),TimeUtc TEXT NOT NULL,Entity TEXT NOT NULL,EntityId INTEGER,Action TEXT NOT NULL,OldValue TEXT,NewValue TEXT,Reason TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS AuditNoEdit BEFORE UPDATE ON Audit BEGIN SELECT RAISE(ABORT,'Audit is immutable'); END;
CREATE TRIGGER IF NOT EXISTS AuditNoDelete BEFORE DELETE ON Audit BEGIN SELECT RAISE(ABORT,'Audit cannot be deleted'); END;
CREATE TABLE IF NOT EXISTS BackupHistory(Id INTEGER PRIMARY KEY,TimeUtc TEXT NOT NULL,File TEXT NOT NULL,Status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS IX_VoucherDay ON Voucher(Day);
CREATE INDEX IF NOT EXISTS IX_VoucherFY ON Voucher(FY,Kind);
CREATE INDEX IF NOT EXISTS IX_PostAccount ON Posting(Account,VoucherId);
CREATE INDEX IF NOT EXISTS IX_PostParty ON Posting(PartyId,Account);
CREATE INDEX IF NOT EXISTS IX_PostEmployee ON Posting(EmployeeId,Account);
CREATE INDEX IF NOT EXISTS IX_PostBank ON Posting(BankId,VoucherId);
CREATE INDEX IF NOT EXISTS IX_PostInstrument ON Posting(InstrumentId,Account);
CREATE INDEX IF NOT EXISTS IX_InvoiceDay ON Invoice(Day,Kind);
CREATE INDEX IF NOT EXISTS IX_InvoiceParty ON Invoice(PartyId,DueDay);
CREATE INDEX IF NOT EXISTS IX_AllocationInvoice ON Allocation(InvoiceId);
CREATE INDEX IF NOT EXISTS IX_AttachmentEntity ON Attachment(Entity,EntityId);
CREATE INDEX IF NOT EXISTS IX_InstrumentMaturity ON Instrument(MaturityDay,Status);
CREATE INDEX IF NOT EXISTS IX_BGExpiry ON BG(ExpiryDay,Status);
